using MreInventorySort;
using SDG.Unturned;

static void Check(bool condition,string message){if(!condition)throw new Exception(message);}
static ItemJar Jar(ushort id,int x,int y,int w=1,int h=1,int rot=0){var i=new Item{id=id};i.Asset.size_x=(byte)w;i.Asset.size_y=(byte)h;return new ItemJar((byte)x,(byte)y,(byte)rot,i);}
static (PlayerInventory inv,Items page,NativeSortSurface surface) Setup(int w=4,int h=2,byte pageId=2){var inv=new PlayerInventory();var p=new Items{width=(byte)w,height=(byte)h};p.items.Add(Jar(2,0,0));p.items.Add(Jar(1,2,0));inv.items[pageId]=p;return(inv,p,new NativeSortSurface(inv,pageId,()=>true));}
var tests=new List<(string name,Action run)>{
 ("sort keeps existing objects and every metadata field",()=>{var(i,p,s)=Setup();var jars=p.items.ToArray();var item=jars[0].item;item.amount=200;item.quality=71;item.state=new byte[]{0,255,3,0};var state=item.state;var r=SortTransaction.Execute(new ISortSurface[]{s});Check(r.Success&&r.Moved==2,"Sort failed");Check(p.items[0]==jars[0]&&p.items[1]==jars[1]&&p.items[0].item==item&&ReferenceEquals(item.state,state)&&item.amount==200&&item.quality==71&&state.SequenceEqual(new byte[]{0,255,3,0}),"Metadata/object identity changed");Check(jars[1].x==0&&jars[0].x==1&&p.DiscardCalls==0,"Wrong layout or discarded item");}),
 ("same ID and metadata never merge distinct items",()=>{var(i,p,s)=Setup();p.items[0].item.id=1;var r=SortTransaction.Execute(new ISortSurface[]{s});Check(r.Success&&p.items.Count==2&&!ReferenceEquals(p.items[0].item,p.items[1].item),"Equal items merged");}),
 ("rotated item keeps rotation and oriented dimensions",()=>{var(i,p,s)=Setup();p.items.Clear();var j=Jar(2,2,0,2,1,1);p.items.Add(j);p.items.Add(Jar(1,0,0));var r=SortTransaction.Execute(new ISortSurface[]{s});Check(r.Success&&j.rot==1&&j.x==1&&j.y==0&&p.DiscardCalls==0,"Rotation changed or wrong bounds");}),
 ("full page non-fitting sorted order remains untouched",()=>{var(i,p,s)=Setup(3,2);p.items.Clear();p.items.Add(Jar(1,2,0));p.items.Add(Jar(2,2,1));p.items.Add(Jar(3,0,0,2,2));var r=SortTransaction.Execute(new ISortSurface[]{s});Check(!r.Success&&p.items[0].x==2&&p.items[1].y==1&&p.RebuildCalls==0&&i.PacketAttempts==0,"Nonfit mutated inventory");}),
 ("overlap fails before mutation",()=>{var(i,p,s)=Setup();p.items[1].x=0;var r=SortTransaction.Execute(new ISortSurface[]{s});Check(!r.Success&&p.RebuildCalls==0&&p.items.Count==2,"Overlap was changed");}),
 ("out of bounds fails without native discard",()=>{var(i,p,s)=Setup();p.items[1].x=250;var r=SortTransaction.Execute(new ISortSurface[]{s});Check(!r.Success&&p.RebuildCalls==0&&p.DiscardCalls==0&&p.items.Count==2,"Invalid item got discarded");}),
 ("oversized state fails before RPC truncation",()=>{var(i,p,s)=Setup();p.items[0].item.state=new byte[256];var r=SortTransaction.Execute(new ISortSurface[]{s});Check(!r.Success&&i.PacketAttempts==0,"Oversized state was sent");}),
 ("255 byte state and zero amount stay intact",()=>{var(i,p,s)=Setup();p.items[0].item.state=Enumerable.Range(0,255).Select(n=>(byte)n).ToArray();p.items[0].item.amount=0;var r=SortTransaction.Execute(new ISortSurface[]{s});Check(r.Success&&p.items[0].item.state.Length==255&&p.items[0].item.amount==0,"Boundary metadata changed");}),
 ("duplicate reference on same page is rejected",()=>{var(i,p,s)=Setup();p.items[1].item=p.items[0].item;var r=SortTransaction.Execute(new ISortSurface[]{s});Check(!r.Success&&p.RebuildCalls==0,"Aliased item accepted");}),
 ("duplicate reference across pages is rejected",()=>{var(i,p,s)=Setup();var other=new Items{width=4,height=2};other.items.Add(new ItemJar(0,0,0,p.items[0].item));i.items[3]=other;var r=SortTransaction.Execute(new ISortSurface[]{s,new NativeSortSurface(i,3,()=>true)});Check(!r.Success&&p.RebuildCalls==0&&other.RebuildCalls==0,"Crosspage alias accepted");}),
 ("unavailable session is rejected before change",()=>{var(i,p,_)=Setup();var s=new NativeSortSurface(i,2,()=>false);var r=SortTransaction.Execute(new ISortSurface[]{s});Check(!r.Success&&p.RebuildCalls==0,"Closed session accepted");}),
 ("replaced page is rejected",()=>{var(i,p,s)=Setup();i.items[2]=new Items{width=4,height=2};var r=SortTransaction.Execute(new ISortSurface[]{s});Check(!r.Success&&p.RebuildCalls==0,"Stale page mutated");}),
 ("changed dimensions are rejected",()=>{var(i,p,s)=Setup();p.width=3;var r=SortTransaction.Execute(new ISortSurface[]{s});Check(!r.Success&&p.RebuildCalls==0,"Dimension change accepted");}),
 ("grid failure rolls back original coordinates",()=>{var(i,p,s)=Setup();p.ThrowNextRebuild=true;var r=SortTransaction.Execute(new ISortSurface[]{s});Check(!r.Success&&r.RolledBack&&!r.NeedsReview&&p.items[0].x==0&&p.items[1].x==2&&p.items.Count==2,"Grid failure lost original layout");}),
 ("single send failure rolls back and resends coordinate union",()=>{var(i,p,s)=Setup();i.FailAtPacket=3;var r=SortTransaction.Execute(new ISortSurface[]{s});Check(!r.Success&&r.RolledBack&&!r.NeedsReview&&p.items[0].x==0&&p.items[1].x==2,"RPC failure did not rollback");Check(i.Packets.Where(v=>v.kind=="remove").Any(v=>v.x==1),"Rollback did not clear attempted new coordinate");}),
 ("permanent send failure preserves server objects and asks for review",()=>{var(i,p,s)=Setup();var items=p.items.Select(j=>j.item).ToArray();i.PermanentNetworkFailure=true;var r=SortTransaction.Execute(new ISortSurface[]{s});Check(!r.Success&&r.RolledBack&&r.NeedsReview&&p.items.Count==2&&ReferenceEquals(p.items[0].item,items[0])&&p.items[1].x==2,"Permanent RPC failure damaged server items");}),
 ("storage persist failure rolls back without replacing Items",()=>{var(i,p,_)=Setup();var storage=new InteractableStorage{items=p,ThrowNextSave=true};var s=new NativeSortSurface(i,2,()=>true,storage);var r=SortTransaction.Execute(new ISortSurface[]{s});Check(!r.Success&&r.RolledBack&&storage.items==p&&p.items.Count==2&&p.items[1].x==2,"Storage save failure corrupted Items");}),
 ("virtual storage hook changes abort rollback overwrite",()=>{var(i,p,_)=Setup();var storage=new InteractableStorage{items=p,onStateRebuilt=new object()};var s=new NativeSortSurface(i,2,()=>true,storage);var r=SortTransaction.Execute(new ISortSurface[]{s});Check(!r.Success&&r.NeedsReview&&p.items.Count==2,"Unknown hook was used");}),
 ("metadata changed by external callback is never overwritten",()=>{var(i,p,s)=Setup();i.OnPacket=()=>{p.items[0].item.amount=77;throw new InvalidOperationException("external mutation");};var r=SortTransaction.Execute(new ISortSurface[]{s});Check(!r.Success&&r.NeedsReview&&p.items[0].item.amount==77&&p.items.Count==2,"Foreign metadata overwritten");}),
 ("multiple pages rollback together",()=>{var(i,p,s)=Setup();var other=new Items{width=4,height=2};other.items.Add(Jar(4,0,0));other.items.Add(Jar(3,2,0));i.items[3]=other;other.ThrowNextRebuild=true;var r=SortTransaction.Execute(new ISortSurface[]{s,new NativeSortSurface(i,3,()=>true)});Check(r.RolledBack&&p.items[1].x==2&&other.items[1].x==2&&p.items.Count+other.items.Count==4,"Crosspage rollback failed");}),
 ("empty clothing page does not break sorting",()=>{var(i,p,s)=Setup();i.items[3]=new Items();var r=SortTransaction.Execute(new ISortSurface[]{s,new NativeSortSurface(i,3,()=>true)});Check(r.Success&&p.items.Count==2&&i.items[3].RebuildCalls==0,"Empty page was mutated or failed");}),
 ("already sorted emits no native writes",()=>{var(i,p,s)=Setup();p.items[0].item.id=1;p.items[1].item.id=2;p.items[1].x=1;var r=SortTransaction.Execute(new ISortSurface[]{s});Check(r.Success&&r.Moved==0&&p.RebuildCalls==0&&i.PacketAttempts==0,"No-op caused writes");}),
 ("server contents remain complete during every packet",()=>{var(i,p,s)=Setup();i.OnPacket=()=>Check(p.items.Count==2&&p.items.Select(j=>j.item).Distinct().Count()==2,"Packet phase held incomplete server inventory");Check(SortTransaction.Execute(new ISortSurface[]{s}).Success,"Packet observer failed");}),
 ("changed session during sending restores server and avoids old client",()=>{var(i,p,_)=Setup();bool open=true;var s=new NativeSortSurface(i,2,()=>open);i.OnPacket=()=>{open=false;throw new InvalidOperationException("close");};var r=SortTransaction.Execute(new ISortSurface[]{s});Check(r.RolledBack&&p.items[1].x==2&&i.Packets.Count==1,"Closed view received recovery contents or server rollback failed");}),
 ("network updates remove all old coordinates before adding new",()=>{var(i,p,s)=Setup();Check(SortTransaction.Execute(new ISortSurface[]{s}).Success,"sort failed");Check(i.Packets.Count==4&&i.Packets[0].kind=="remove"&&i.Packets[1].kind=="remove"&&i.Packets[2].kind=="add"&&i.Packets[3].kind=="add","Packet order invalid");}),
 ("protected equipment page is not selected by transaction",()=>{var(i,p,s)=Setup();var equipped=new Items{width=1,height=1};var weapon=Jar(500,0,0);equipped.items.Add(weapon);i.items[0]=equipped;Check(SortTransaction.Execute(new ISortSurface[]{s}).Success&&i.items[0].items[0]==weapon&&equipped.RebuildCalls==0,"Equipment slot touched");}),
 ("large grid is rejected",()=>{var(i,p,s)=Setup(255,255);var r=SortTransaction.Execute(new ISortSurface[]{s});Check(!r.Success&&p.RebuildCalls==0,"Huge grid allowed");}),
 ("unrecognized world item jar is rejected before mutation",()=>{var(i,p,s)=Setup();p.items[0].interactableItem=new object();var r=SortTransaction.Execute(new ISortSurface[]{s});Check(!r.Success&&p.RebuildCalls==0,"Ground-linked item accepted");})
};
foreach(var t in tests){t.run();Console.WriteLine("PASS: "+t.name);}
Console.WriteLine($"Passed {tests.Count} inventory sort scenarios. Unity/network/ownership behavior requires separate game acceptance.");
